deleted = 0
AND tenant_id = #{tenantId}

    AND operator = #{operator}

AND join_status IS NOT NULL
AND join_status <> ''
AND join_status <> '已中标'

    AND province = #{province}


    AND city LIKE CONCAT('%', #{city}, '%')


    AND industry = #{industry}


    AND lost_reason LIKE CONCAT('%', #{lostReason}, '%')


    AND  LIKE CONCAT('%', #{reviewStatus}, '%')


    AND (project_name LIKE CONCAT('%', #{keyword}, '%')
    OR title LIKE CONCAT('%', #{keyword}, '%')
    OR tenderer LIKE CONCAT('%', #{keyword}, '%')
    OR win_tenderer LIKE CONCAT('%', #{keyword}, '%'))


    AND publish_time >= #{beginDate}


    AND publish_time <= #{endDate}
